import{_ as o,o as i,c as a,a0 as c}from"./chunks/framework.BLL-IG04.js";const h=JSON.parse('{"title":"Command-Line Help for mimus","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),s={name:"reference/cli.md"};function t(r,e,m,d,l,n){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="command-line-help-for-mimus" tabindex="-1">Command-Line Help for <code>mimus</code> <a class="header-anchor" href="#command-line-help-for-mimus" aria-label="Permalink to &quot;Command-Line Help for `mimus`&quot;">​</a></h1><p>This document contains the help content for the <code>mimus</code> command-line program.</p><p><strong>Command Overview:</strong></p><ul><li><a href="#mimus"><code>mimus</code>↴</a></li><li><a href="#mimus-init"><code>mimus init</code>↴</a></li><li><a href="#mimus-check"><code>mimus check</code>↴</a></li><li><a href="#mimus-fix"><code>mimus fix</code>↴</a></li><li><a href="#mimus-audit"><code>mimus audit</code>↴</a></li><li><a href="#mimus-report"><code>mimus report</code>↴</a></li><li><a href="#mimus-doctor"><code>mimus doctor</code>↴</a></li><li><a href="#mimus-coverage"><code>mimus coverage</code>↴</a></li><li><a href="#mimus-claims"><code>mimus claims</code>↴</a></li></ul><h2 id="mimus" tabindex="-1"><code>mimus</code> <a class="header-anchor" href="#mimus" aria-label="Permalink to &quot;`mimus`&quot;">​</a></h2><p>Spots the cuckoo eggs in your repo — claim verification: docs-as-tests, memory audit</p><p><strong>Usage:</strong> <code>mimus [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="subcommands" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>init</code> — Detect sources -&gt; mimus.toml + rules/ scaffold</li><li><code>check</code> — Verify claims. Mechanical tier by default</li><li><code>fix</code> — Apply mechanical rewrites for confirmed violations</li><li><code>audit</code> — Trust-score .kuda/ cards vs source</li><li><code>report</code> — Full violations list with evidence</li><li><code>doctor</code> — Checker/config/kuda-index health</li><li><code>coverage</code> — Doc coverage — which indexed symbols no doc ever names. The reverse direction of <code>check</code>: code has it, docs silent</li><li><code>claims</code> — Dump extracted claims (kind/source/line) — tuning aid for the extractor&#39;s precision on real docs</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--config &lt;CONFIG&gt;</code> — Config path (else $MIMUS_CONFIG, ./mimus.toml, ~/.config/mimus/mimus.toml)</p></li><li><p><code>--format &lt;FORMAT&gt;</code> — Output format: human | json</p><p>Default value: <code>human</code></p></li></ul><h2 id="mimus-init" tabindex="-1"><code>mimus init</code> <a class="header-anchor" href="#mimus-init" aria-label="Permalink to &quot;`mimus init`&quot;">​</a></h2><p>Detect sources -&gt; mimus.toml + rules/ scaffold</p><p><strong>Usage:</strong> <code>mimus init</code></p><h2 id="mimus-check" tabindex="-1"><code>mimus check</code> <a class="header-anchor" href="#mimus-check" aria-label="Permalink to &quot;`mimus check`&quot;">​</a></h2><p>Verify claims. Mechanical tier by default</p><p><strong>Usage:</strong> <code>mimus check [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--all</code> — Include the semantic tier (advisory only, never gates)</li><li><code>--no-cmd</code> — Skip command claims — the PATH probe is machine-dependent</li></ul><h2 id="mimus-fix" tabindex="-1"><code>mimus fix</code> <a class="header-anchor" href="#mimus-fix" aria-label="Permalink to &quot;`mimus fix`&quot;">​</a></h2><p>Apply mechanical rewrites for confirmed violations</p><p><strong>Usage:</strong> <code>mimus fix [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--dry</code> — Show the plan, write nothing</li><li><code>--semantic</code> — Agentic tier: agent proposes corrected claim text for semantic (REFUTED) findings. Needs [check].acp_cmd</li></ul><h2 id="mimus-audit" tabindex="-1"><code>mimus audit</code> <a class="header-anchor" href="#mimus-audit" aria-label="Permalink to &quot;`mimus audit`&quot;">​</a></h2><p>Trust-score .kuda/ cards vs source</p><p><strong>Usage:</strong> <code>mimus audit</code></p><h2 id="mimus-report" tabindex="-1"><code>mimus report</code> <a class="header-anchor" href="#mimus-report" aria-label="Permalink to &quot;`mimus report`&quot;">​</a></h2><p>Full violations list with evidence</p><p><strong>Usage:</strong> <code>mimus report</code></p><h2 id="mimus-doctor" tabindex="-1"><code>mimus doctor</code> <a class="header-anchor" href="#mimus-doctor" aria-label="Permalink to &quot;`mimus doctor`&quot;">​</a></h2><p>Checker/config/kuda-index health</p><p><strong>Usage:</strong> <code>mimus doctor</code></p><h2 id="mimus-coverage" tabindex="-1"><code>mimus coverage</code> <a class="header-anchor" href="#mimus-coverage" aria-label="Permalink to &quot;`mimus coverage`&quot;">​</a></h2><p>Doc coverage — which indexed symbols no doc ever names. The reverse direction of <code>check</code>: code has it, docs silent</p><p><strong>Usage:</strong> <code>mimus coverage</code></p><h2 id="mimus-claims" tabindex="-1"><code>mimus claims</code> <a class="header-anchor" href="#mimus-claims" aria-label="Permalink to &quot;`mimus claims`&quot;">​</a></h2><p>Dump extracted claims (kind/source/line) — tuning aid for the extractor&#39;s precision on real docs</p><p><strong>Usage:</strong> <code>mimus claims [OPTIONS]</code></p><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--all</code> — Include card-prose Behavior claims too</li></ul><hr><p><small><i> This document was generated automatically by <a href="https://crates.io/crates/clap-markdown"><code>clap-markdown</code></a>. </i></small></p>',43)])])}const p=o(s,[["render",t]]);export{h as __pageData,p as default};
